/// <summary>The between-missions events (rulebook phases.between-missions), in their order, on copies of the people: what the next
/// mission inherits, as debrief lines with causes (K7, §08). `mission` is this mission's number in the campaign (the Handover: 1).</summary>
public Between BetweenMissions(Investigation inv, int mission = 1)
{
    var b = new Between();
    var copies = new Dictionary<Person, Person>();
    Person C(Person p)
    {
        if (copies.TryGetValue(p, out var c)) return c;
        c = new Person { Role = p.Role, Id = p.Id, Name = p.Name, Temperament = p.Temperament, Need = p.Need, Job = p.Job, Turned = p.Turned, NeedMet = p.NeedMet, Down = p.Down, KRoutine = p.KRoutine, KNeed = p.KNeed, KTemperament = p.KTemperament, Place = p.Place, Suspected = p.Suspected, Record = p.Record, Size = p.Size, Holder = p.Holder };
        Array.Copy(p.Sc, c.Sc, 4); c.Memory.AddRange(p.Memory); foreach (var a in p.KnownRefused) c.KnownRefused.Add(a);
        copies[p] = c; return c;
    }
    var everyone = new List<Person>(People); foreach (var w in Walkers) everyone.Add(w.P);
    everyone.Sort((x, y) => string.CompareOrdinal(x.Id, y.Id));
    var byId = new Dictionary<string, Person>(StringComparer.Ordinal); foreach (var p in everyone) byId[p.Id] = p;
    void line(string l, Person who, string detail) => b.Lines.Add(new BetweenLine { Line = l, Who = who.Role.Length > 0 ? who.Role : who.Id, Detail = detail });
    string fmt(int v) => v.ToString(System.Globalization.CultureInfo.InvariantCulture);

    // ladder.job: each job done this mission, exposed or not (rulebook exposure: questioned, or a watcher logged an operative beside them)
    foreach (var p in everyone)
    {
        if (!p.Turned || p.Down) continue;
        foreach (var m in p.Memory)
        {
            if (m.Act != "job") continue;
            var c = C(p); bool exposed = ExposedByWatcher.Contains(p.Role) || inv.Exposed.Contains(p.Role);
            string move = exposed ? "job-exposed" : "job-unexposed";
            var (k, by) = R.Ladders[move][0];
            int was = c.Sc[k]; foreach (var (kk, bb) in R.Ladders[move]) c.Sc[kk] = R.Clamp(kk, c.Sc[kk] + bb);
            line("ladder", p, $"{move}: {Rules.ScaleNames[k]} {R.Step(k, was)} → {R.Step(k, c.Sc[k])}");
        }
    }
    // contact.informs, mercenary.sells: one ambush in the next mission however many (Motive's review #4)
    foreach (var p in everyone)
    {
        if (!p.Turned || p.Down) continue;
        var c = C(p);
        if (c.Sc[Rules.Resentment] >= R.ScaleMax[Rules.Resentment]) { b.Ambush = true; b.AmbushBy.Add(c.Role.Length > 0 ? c.Role : c.Id); line("informer", p, "resentment " + R.Step(Rules.Resentment, c.Sc[Rules.Resentment]) + ": sells a route; an ambush is scheduled"); }
        else if (c.Temperament == "mercenary" && R.BandOf(Standing) == Band.Menace && c.Sc[Rules.Loyalty] <= R.ScaleMin[Rules.Loyalty]) { b.Ambush = true; b.AmbushBy.Add(c.Role.Length > 0 ? c.Role : c.Id); line("sold", p, "a Mercenary in a Menace district who owes the cell nothing sells a route"); }
    }
    // debtor.lapses: a met debt ends the ties that carried it
    var ties = People2?.Ties;
    foreach (var p in everyone)
    {
        if (!p.NeedMet || p.Need != "debt" || ties == null || !ties.TryGetValue(p.Id, out var ts)) continue;
        foreach (var (kind, with) in ts) if (kind == "debtor") line("tie-lapsed", p, "debtor tie to " + with + ": the debt is cleared");
    }
    // need.replaced (Sky Q2): from the person's own stream, {person}/need/{mission}
    foreach (var p in everyone)
    {
        if (!p.NeedMet) continue;
        var c = C(p); string old = c.Need;
        c.Need = ReplacementNeed(c, mission); c.NeedMet = false;
        if (People2 != null) { c.Record = People2.DefaultRecord(c.Need); c.Size = c.Record.Length > 0 ? People2.Records[c.Record].size : ""; c.Holder = c.Record.Length > 0 ? "beyond" : ""; } // brief 017 phase 1: the kind's record, no draw
        if (c.Turned) c.KNeed = true; else c.KNeed = false;
        line("need-replaced", p, $"{old} → {c.Need}{(c.Turned ? " (told free: a contact)" : " (Listen again)")}");
    }
    // word.passes (K3, Sky Q6): facts, never opinion, along family and workmate ties, one hop; an obliged contact keeps quiet
    if (ties != null)
        foreach (var p in everyone)
        {
            var facts = FactsOfWitnessed(p);
            if (facts.Count == 0 || C(p).Sc[Rules.Loyalty] >= R.WordQuietLoyalty || !ties.TryGetValue(p.Id, out var ts)) continue;
            foreach (var (kind, with) in ts)
            {
                if ((kind != "family" && kind != "workmate") || !byId.TryGetValue(with, out var q)) continue;
                var cq = C(q); var held = FactsOf(cq); var add = facts.FindAll(f => !held.Contains(f));
                if (add.Count == 0) continue;
                cq.Memory.Add(new Mem { Act = "told", By = p.Id, Place = cq.Place, Tick = Tick, Witnessed = false, Told = string.Join("|", add) });
                line("word", p, $"tells {(q.Role.Length > 0 ? q.Role : q.Id)} ({kind}): {string.Join(", ", add)}");
            }
        }
    // standing.word (brief 014): each person the cell helped, pressured or knocked out, alive, with a tie of a kind in standing.word.ties,
    // tells them how a stranger treated them: a feeling, never a fact, so no memory or knowledge moves; harm outranks help
    var word = new List<(int delta, string cause, string who)>();
    foreach (var p in everyone)
    {
        var done = DoneTo(p);
        if (done.Count == 0 || !Alive(p) || ties == null || !ties.TryGetValue(p.Id, out var wts) || !wts.Exists(t => R.WordTies.Contains(t.Item1))) continue;
        string how = done.Contains("pressured") ? "pressured" : done.Contains("knocked-out") ? "knocked-out" : "helped";
        int d = how == "helped" ? R.WordStandingStep : -R.WordStandingStep;
        word.Add((d, "word-" + how, Who(p))); b.Word.Add((Who(p), how == "helped" ? "hero" : "menace"));
    }
    // contact.introduces: who each contact could introduce (the pick is the player's order in the debrief)
    if (ties != null)
        foreach (var p in everyone)
        {
            if (!p.Turned || p.Down || !ties.TryGetValue(p.Id, out var ts)) continue;
            var can = new List<string>();
            foreach (var (kind, with) in ts) if (R.TieIntroduces.TryGetValue(kind, out var intro) && intro && byId.TryGetValue(with, out var q) && !q.Turned && !q.Has(R.RefusedAct)) can.Add(with + " (" + kind + ")");
            if (can.Count > 0) line("introduced", p, "can introduce " + string.Join(", ", can) + ", up to " + fmt(R.IntroductionsPerContact) + " (the player's pick)");
        }
    Takedowns(b, C, byId, line, fmt);
    Custody(b, fmt); // brief 018 §3: who was left behind, the car seen, each captive (GameGetaway.cs)
    StandingNext(b, word, fmt);
    foreach (var p in everyone) if (p.Turned) b.Contacts.Add(C(p));

// An order script (brief 011 B, Waymark's route scripts): a start state and timed orders in the engine's order format.
// {"schema": "suborned.sim.script/1", "mission": "handover", "start": {...}, "orders": [{"tick": 0, "op": "scout", "do": "move", "to": "d:Courtyard"}, ...], "until": 4800}
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;

namespace Suborned.Sim
{
    /// <summary>A run record (Redline E4): what a replay must match. inputs = the inputs' canonical hash; engine = Engine.Version (and
    /// the assembly MVID, for information); start = the start state's hash; checkpoints = every (tick, hash); outcome.</summary>
    public sealed class Expect
    {
        public string Inputs = "", Engine = "", Mvid = "", Start = "", Outcome = ""; public readonly List<(int tick, string hash)> Checkpoints = new List<(int, string)>();
    }

    public sealed class Script
    {
        public Start Start = new Start(); public readonly List<Order> Orders = new List<Order>(); public int Until; public Expect? Expect;
        public static Script Parse(string json)
        {
            var n = JNode.Parse(json, "script");
            n.Only("schema", "mission", "note", "start", "orders", "until", "expect");
            if (n["schema"].Str() != "suborned.sim.script/1") throw new FormatException("script schema is not suborned.sim.script/1");
            if (n["mission"].Str() != "handover") throw new FormatException("only the Handover plays (brief 011)");
            var s = new Script { Start = Start.Parse(n.Opt("start")), Until = n.Opt("until")?.Int() ?? 0 }; // 0: to the mission's close
            foreach (var o in n["orders"].Items) s.Orders.Add(Order.Parse(o));
            if (n.Opt("expect") is JNode e)
            {
                e.Only("inputs", "engine", "mvid", "start", "outcome", "checkpoints");
                var x = new Expect { Inputs = e["inputs"].Str(), Engine = e["engine"].Str(), Mvid = e.Opt("mvid")?.Str() ?? "", Start = e["start"].Str(), Outcome = e["outcome"].Str() };
                foreach (var c in e["checkpoints"].Items) { var pair = c.Items; if (pair.Count != 2) throw new FormatException($"{c.Path}: [tick, hash]"); x.Checkpoints.Add((pair[0].Int(), pair[1].Str())); }
                s.Expect = x;
            }
            return s;
        }
        /// <summary>The run as a script: its start state, its orders (rejected ones too: they are the player's), and its record.</summary>
        public static string Write(Game g, ulong inputsHash)
        {
            var w = new JWriter().Obj().Prop("schema", "suborned.sim.script/1").Prop("mission", "handover").Key("start").Raw(g.Start.Canonical()).OpenArr("orders");
            foreach (var (o, _, _, _) in g.Orders) o.Write(w);
            w.EndArr().Prop("until", g.Tick);
            w.Open("expect").Prop("inputs", Hash.Hex(inputsHash)).Prop("engine", Engine.Version).Prop("mvid", Engine.Mvid).Prop("start", Hash.Hex(g.StartHash)).Prop("outcome", g.Result.ToString().ToLowerInvariant());
            w.OpenArr("checkpoints"); foreach (var (t, h) in g.Checkpoints) w.Arr().Num(t).Str(Hash.Hex(h)).EndArr(); w.EndArr().EndObj();
            return w.EndObj().ToString();
        }
        /// <summary>Check a replay against the record: "" if it matches, else the first difference.</summary>
        public string Verify(Game g, ulong inputsHash)
        {
            if (Expect == null) return "";
            if (Expect.Inputs != Hash.Hex(inputsHash)) return $"the inputs differ from the record ({Expect.Inputs} recorded, {Hash.Hex(inputsHash)} now)";
            if (Expect.Engine != Engine.Version) return $"the engine differs from the record ({Expect.Engine} recorded, {Engine.Version} now)";
            if (Expect.Start != Hash.Hex(g.StartHash)) return "the start state differs from the record";
            int n = Math.Min(Expect.Checkpoints.Count, g.Checkpoints.Count);
            for (int i = 0; i < n; i++)
                if (Expect.Checkpoints[i].tick != g.Checkpoints[i].tick || Expect.Checkpoints[i].hash != Hash.Hex(g.Checkpoints[i].hash))
                    return $"checkpoint {i} differs at tick {g.Checkpoints[i].tick}";
            if (Expect.Checkpoints.Count != g.Checkpoints.Count) return $"{g.Checkpoints.Count} checkpoints, the record has {Expect.Checkpoints.Count}";
            if (Expect.Outcome != g.Result.ToString().ToLowerInvariant()) return "the outcome differs from the record";
            return "";
        }
    }

    public static class Report
    {
        public static string Clock(int tick) { int s = tick / Game.Hz; return $"{s / 60}:{(s % 60).ToString("00", CultureInfo.InvariantCulture)}.{tick % Game.Hz}"; }
        public static string Json(string id, Game g, List<(bool ok, string what)> checks, bool replayIdentical)
        {
            var w = new JWriter().Obj().Prop("id", id).Prop("outcome", g.Result.ToString().ToLowerInvariant()).Prop("fail", g.FailCode).Prop("tick", g.Tick)
                .Prop("cash", g.Cash).Prop("trail", g.Trail).Prop("alert", g.Alert).Prop("gunfire", g.Gunfire).Prop("standing", g.Standing)
                .Prop("startHash", Hash.Hex(g.StartHash)).Prop("finalHash", Hash.Hex(g.Checkpoints[g.Checkpoints.Count - 1].hash)).Prop("replayIdentical", replayIdentical);
            if (g.Cause != null) { w.Key("cause"); g.Cause.Write(w); } // the fail camera's culprit (FailCause.cs): written only when the run failed or withdrew
            w.OpenArr("checkpoints"); foreach (var (t, h) in g.Checkpoints) w.Obj().Prop("tick", t).Prop("hash", Hash.Hex(h)).EndObj(); w.EndArr();
            w.OpenArr("checks"); foreach (var c in checks) w.Obj().Prop("ok", c.ok).Prop("what", c.what).EndObj(); w.EndArr();
            w.OpenArr("orders"); foreach (var (o, ok, code, why) in g.Orders) { w.Obj().Key("order").Raw(o.ToString()).Prop("ok", ok); if (!ok) w.Prop("code", code).Prop("why", why); w.EndObj(); } w.EndArr();
            w.OpenArr("ledger"); foreach (var (t, what, d, now, cause) in g.Ledger) w.Obj().Prop("tick", t).Prop("what", what).Prop("delta", d).Prop("now", now).Prop("cause", cause).EndObj(); w.EndArr();
            w.OpenArr("log"); foreach (var l in g.Log) w.Obj().Prop("tick", l.Tick).Prop("code", l.Code).Prop("text", l.Text).EndObj(); w.EndArr();
            if (g.Result == Outcome.Success) { w.Key("debrief"); var d = new JWriter(); Debrief.Of(g).Write(d); w.Raw(d.ToString()); }
            return w.EndObj().ToString();
        }
    }
}

        }
    }

    /// <summary>A tiny JSON writer for the CLI's output and the order log: ordinal, invariant, no floats.</summary>
    public sealed class JWriter
    {
        readonly StringBuilder b = new StringBuilder();
        readonly Stack<bool> first = new Stack<bool>();
        void Sep() { if (first.Count > 0) { if (!first.Peek()) b.Append(','); first.Pop(); first.Push(false); } }
        public JWriter Obj() { Sep(); b.Append('{'); first.Push(true); return this; }
        public JWriter EndObj() { first.Pop(); b.Append('}'); return this; }
        public JWriter Arr() { Sep(); b.Append('['); first.Push(true); return this; }
        public JWriter EndArr() { first.Pop(); b.Append(']'); return this; }
        public JWriter Key(string k) { Sep(); Quote(k); b.Append(':'); first.Push(true); keyPending = true; return this; }
        bool keyPending;
        void Value(string raw) { if (keyPending) { keyPending = false; first.Pop(); b.Append(raw); return; } Sep(); b.Append(raw); }
        public JWriter Str(string v) { var t = new JWriter(); t.Quote(v); Value(t.b.ToString()); return this; }
        public JWriter Num(long v) { Value(v.ToString(CultureInfo.InvariantCulture)); return this; }
        public JWriter Bool(bool v) { Value(v ? "true" : "false"); return this; }
        public JWriter Null() { Value("null"); return this; }
        public JWriter Raw(string json) { Value(json); return this; }
        public JWriter Prop(string k, string v) => Key(k).Str(v);
        public JWriter Prop(string k, long v) => Key(k).Num(v);
        public JWriter Prop(string k, bool v) => Key(k).Bool(v);
        void Quote(string v)
        {
            b.Append('"');
            foreach (var c in v)
            {
                if (c == '"') b.Append("\\\""); else if (c == '\\') b.Append("\\\\"); else if (c == '\n') b.Append("\\n");
                else if (c < 0x20) b.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture)); else b.Append(c);
            }
            b.Append('"');
        }
        public JWriter Open(string k) { Key(k); keyPending = false; first.Pop(); b.Append('{'); first.Push(true); return this; }
        public JWriter OpenArr(string k) { Key(k); keyPending = false; first.Pop(); b.Append('['); first.Push(true); return this; }
        public override string ToString() => b.ToString();
    }
}

// dotnet test sim/Suborned.Sim.Tests — the done-check of brief 011 A: the 28 scenarios pass headless; the same orders give
// byte-identical checksums twice; a replay from the order log matches; the rules agree with contracts/rules/rulebook.test.ts.
using System;
using System.Collections.Generic;
using System.Linq;
using Suborned.Sim;
using Xunit;

public static class Repo
{
    public static readonly Engine.Inputs Inputs = Engine.Load(Engine.FindRoot(AppContext.BaseDirectory));
}

public class ScenarioTests
{
    public static IEnumerable<object[]> Ids => Scenarios.All.Select(s => new object[] { s.Id });

    [Theory, MemberData(nameof(Ids))]
    public void Passes(string id)
    {
        var run = Scenarios.Run(Repo.Inputs, Scenarios.Find(id)!);
        var failed = run.Checks.Where(c => !c.ok).Select(c => c.what).ToList();
        Assert.True(failed.Count == 0, $"{id}: " + string.Join("; ", failed));
        Assert.NotEmpty(run.Checks);
    }

    [Theory, MemberData(nameof(Ids))]
    public void SameOrdersSameChecksumsTwice(string id)
    {
        var a = Scenarios.Run(Repo.Inputs, Scenarios.Find(id)!).G;
        var b = Scenarios.Run(Repo.Inputs, Scenarios.Find(id)!).G;
        Assert.Equal(a.Checkpoints, b.Checkpoints);
        Assert.Equal(a.StartHash, b.StartHash);
    }

    [Theory, MemberData(nameof(Ids))]
    public void ReplaysFromStartStateAndOrders(string id)
    {
        var played = Scenarios.Run(Repo.Inputs, Scenarios.Find(id)!).G;
        var replay = Engine.Replay(Repo.Inputs, played);
        Assert.Equal(played.Checkpoints, replay.Checkpoints);
        Assert.Equal(played.Result, replay.Result);
    }

    [Fact]
    public void TwentyEightPortedPlusTheEnginesNCases()
    {
        Assert.Equal(28, Scenarios.All.Count(s => s.Id.StartsWith("S")));
        Assert.Equal(Enumerable.Range(1, 28).Select(i => $"S{i:00}"), Scenarios.All.Where(s => s.Id.StartsWith("S")).Select(s => s.Id));
    }

    [Fact]
    public void OrdersAfterAnOrderEndsTheMissionReplayToo()
    {
        // Keel 2026-10-16 (found while re-casting r016): an order that ends the mission (withdraw, an entry seen) leaves the tick where it
        // is, so anything given after it at that tick is refused (mission-over) and is still the player's, in the record. The replay plays it.
        var g = Engine.New(Repo.Inputs); var r = new Run(g);
        r.Wait(Game.T(30));
        Assert.True(g.Issue(new Order { Tick = g.Tick, Do = "withdraw" }).ok);
        Assert.True(g.Over);
        Assert.Equal("mission-over", g.Issue(new Order { Tick = g.Tick, Op = "scout", Do = "move", To = "d:Courtyard" }).code);
        g.Finish();
        var replay = Engine.Replay(Repo.Inputs, g);
        Assert.Equal(g.Orders.Count, replay.Orders.Count);
        Assert.Equal(g.Checkpoints, replay.Checkpoints);
        Assert.Equal(g.Result, replay.Result);
    }

    [Fact]
    public void AScriptRoundTripsThroughTheOrderFormat()
    {
        var played = Scenarios.Run(Repo.Inputs, Scenarios.Find("S10")!).G;
        var script = Script.Parse(Script.Write(played, Repo.Inputs.Hash));
        var replay = Engine.Play(Repo.Inputs, script.Start, script.Orders, script.Until);
        Assert.Equal(Outcome.Success, replay.Result);
        Assert.Equal(played.Checkpoints, replay.Checkpoints);
        Assert.Equal("", script.Verify(replay, Repo.Inputs.Hash));
        Assert.NotEqual("", script.Verify(replay, Repo.Inputs.Hash ^ 1)); // other inputs: the record says so
    }
}

