        var w = Engine.FromTexts(Win(I.Rulebook), Win(I.PeopleRules), Win(I.Site), Win(I.People), I.Provisional.Length > 0 ? Win(I.Provisional) : null, I.Takedown.Length > 0 ? Win(I.Takedown) : null, I.Rounds.Length > 0 ? Win(I.Rounds) : null);
